      oldOptions: ["Petty / Minor", "Lesser", "Intermediate", "Greater", "Overgod", "Cosmic / Outer", "Variable", "Unknown", "Other"],
      newOptions: ["Petty / Minor", "Lesser", "Intermediate", "Greater", "High God", "Overgod", "Cosmic / Outer", "Variable", "Unknown", "Other"],
