    name,
    description: tabulaStr(doc.description),
    tags: Array.isArray(doc.tags) ? doc.tags.filter(x => typeof x === "string") : [],
    layout: "tabula",
    root: coerced,
    createdAt: typeof doc.createdAt === "string" ? doc.createdAt : isoNow(),
